contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint withdrawAmount) public {
        require(withdrawAmount <= address(c).balance, "insufficient balance");

        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balanceBefore = address(c).balance;

        c.withdraw(withdrawAmount); if (__ESBMC_reverted()) return;

        uint balanceAfter = address(c).balance;
        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

        assert(
            ownerAfter == ownerBefore &&
            depositsAfter == depositsBefore &&
            balanceAfter + withdrawAmount == balanceBefore
        );
    }
}

